* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * ***  ACE Audio Compression & Expansion**  Copyright (C) 1988, 1990, Apple Computer, Inc., All Rights Reserved**  Authors:**  NAME				PERPETRATOR CODE	WHEREABOUTS*  ===============  =================== =============================================================*  Jim Merritt		JAM					Apple II Strategic Technologies Engineering, M/S 70AL, x47737*  Dave Lyons		DAL					Apple II SW Engineering, M/S 70AL, x49502**  Change History (we join the toolkit already in progress!):**  DATE				PERPETRATOR			CHANGE*  ===============  =================== =============================================================*  April 7, 1988	JAM					1.1P, corresponds to ERS Rev. 1:1*  April 14,1988	JAM					1.1P+, fixes error return in ACEExp/CompBegin*  May 20,1988		JAM					1.1P++, fixes DataOverlap error return in*										ACECompress (Bug Report # BCOETF514)*										(compressed dataset sizes were not being figured*										correctly, either, so that was fixed, too)*  90.02.17			JAM					Begin 1.2P, speed enhancements to Expand*										Expand is now much closer to a classical state machine, utilizing*										tables that precompute data that the old ACE used to generate for*										every sample;  the innermost loop has been unwound as well.*										Code and new macros all work fine, but much work needs to be done*										to clean up the code and document it more thoroughly.*										In particular, the "magic" behind the data table generation*										needs to be explained.  Compress is as yet untouched, and will*										probably require separate tables of its own.*										No new ACE calls have been introduced this time around, and all*										existing calls work exactly as before.	The only difference between*										this tool and the 1.1 version is its size (1.2 is about 5x larger)*										and its speed (1.2 is about 3x faster in expansion).*  90.05.23			JAM					Version 1.2d2.  Rearranged ACE direct page to move*										expansion state information to the bottom of DP.*										First 16 bytes of DP are now reserved for "saxel info."*  25-Sep-90		Dave Lyons (DAL)	version $8103*       								Adding two calls:  $0D1D GetACEExpState and $0E1D SetACEExpState.*       								Removed some unnecessary code (several places) that was constructing*       								error numbers from the on-the-fly X register call number, when the*       								equates for those errors were already hard-coded to include toolset*       								number anyway.*       								Saved a few bytes by changing some CMP #ErrorCondition's into CLC or*      									SEC as appropriate.*  91.07.21			JAM					Dave missed a bcc in the part of GetACEExpState where he zeroes*										the unused portion of the saxel to zeroes.  This fixes*										BRC #1008113.* 5-Feb-92			DAL					Changed version number to 1.3 final ($0103).** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	MACRO&lab	ExpandingMan	&samplewidth,&bytenow	LCLA	&phase	LCLC	&IDelt	LCLC	&IDeltX	LCLC	&NewExpIPoint		IF (&samplewidth=3) THEN&phase	SETA	(&bytenow AND %0000000000001111)&IDelt	SETC	'IDelt3B'&IDeltX	SETC	'IDeltX3B'&NewExpIPoint	SETC	'New3BExpIPoint'	ELSEIF (&samplewidth=4) THEN&phase	SETA	(&bytenow AND %0000000000001111)&IDelt	SETC	'IDelt4B'&IDeltX	SETC	'IDeltX4B'&NewExpIPoint	SETC	'New4BExpIPoint'	ENDIF&lab;	Get IDecM		IF		(&samplewidth=3) THEN		IF (&phase=0) THEN; 3-bit, phase 0			sty tempvalue		; save dest index temporarily			ldy #4				; load from the most distant down,			lda [srcptr],y		;   so we end up with data we want now			sta buff+4			;   (buff+0) already in the accumulator.			ldy #2			lda [srcptr],y			sta buff+2			lda [srcptr]			sta	buff			ldy tempvalue		; y once again contains the destptr index			asl a		ELSEIF (&phase=1) THEN; 3-bit, phase 1			lda	buff			ror a			ror a		ELSEIF (&phase=2) THEN; 3-bit, phase 2			lda buff			rol a			rol a			rol a			xba		ELSEIF (&phase=3) THEN; 3-bit, phase 3			lda buff+1		ELSEIF (&phase=4) THEN; 3-bit, phase 4			lda buff+1			ror a			ror a			ror a		ELSEIF (&phase=5) THEN; 3-bit, phase 5			lda	buff+1			rol a			rol a			xba		ELSEIF (&phase=6) THEN; 3-bit, phase 6			lda buff+2			ror a		ELSEIF (&phase=7) THEN; 3-bit, phase 7			lda buff+2			ror a			ror a			ror a			ror a		ELSEIF (&phase=8) THEN; 3-bit, phase 8			lda buff+3			asl a		ELSEIF (&phase=9) THEN; 3-bit, phase 9			lda buff+3			ror a			ror a		ELSEIF (&phase=10) THEN; 3-bit, phase 10			lda buff+3			rol a			rol a			rol a			xba		ELSEIF (&phase=11) THEN; 3-bit, phase 11			lda buff+4		ELSEIF (&phase=12) THEN; 3-bit, phase 12			lda buff+4			ror a			ror a			ror a		ELSEIF (&phase=13) THEN; 3-bit, phase 13			lda buff+4			rol a			rol a			xba		ELSEIF (&phase=14) THEN; 3-bit, phase 14			lda buff+5			ror a		ELSEIF (&phase=15) THEN; 3-bit, phase 15			lda buff+5			ror a			ror a			ror a			ror a		ENDIF		and #%0000000000001110	ELSEIF	(&samplewidth=4) THEN		IF		(&phase=0) THEN; 4-bit, phase 0			sty tempvalue			ldy #6			lda [srcptr],y			sta buff+6			ldy #4			lda [srcptr],y			sta buff+4			ldy #2			lda [srcptr],y			sta buff+2			lda [srcptr]			sta	buff			ldy tempvalue			asl a		ELSEIF	(&phase=1) THEN; 4-bit, phase 1			lda buff			ror a			ror a			ror a		ELSEIF	(&phase=2) THEN; 4-bit, phase 2			lda buff+1			asl a		ELSEIF	(&phase=3) THEN; 4-bit, phase 3			lda buff+1			ror a			ror a			ror a		ELSEIF	(&phase=4) THEN; 4-bit, phase 4			lda buff+2			asl a		ELSEIF	(&phase=5) THEN; 4-bit, phase 5			lda buff+2			ror a			ror a			ror a		ELSEIF	(&phase=6) THEN; 4-bit, phase 6			lda buff+3			asl a		ELSEIF	(&phase=7) THEN; 4-bit, phase 7			lda buff+3			ror a			ror a			ror a		ELSEIF	(&phase=8) THEN; 4-bit, phase 8			lda	buff+4			asl a		ELSEIF	(&phase=9) THEN; 4-bit, phase 9			lda buff+4			ror a			ror a			ror a		ELSEIF	(&phase=10) THEN; 4-bit, phase 10			lda buff+1+4			asl a		ELSEIF	(&phase=11) THEN; 4-bit, phase 11			lda buff+1+4			ror a			ror a			ror a		ELSEIF	(&phase=12) THEN; 4-bit, phase 12			lda buff+2+4			asl a		ELSEIF	(&phase=13) THEN; 4-bit, phase 13			lda buff+2+4			ror a			ror a			ror a		ELSEIF	(&phase=14) THEN; 4-bit, phase 14			lda buff+3+4			asl a		ELSEIF	(&phase=15) THEN; 4-bit, phase 15			lda buff+3+4			ror a			ror a			ror a		ENDIF		and #%0000000000011110	ENDIF	;	at this point, IDecM<<2 is in acc;	x contains index for [ExIPoint, IDecM] from previous iteration	ora &NewExpIPoint,x	; preshifted left NumBits+1 places	tax					; x now has current index value = [ExpIPoint, IDecM]	lda	&IDelt,x	clc	adc ExpMAEDA	sta ExpMAEDA	; at this point, expanded byte value is in A	beq	@1	bpl	@2@1	lda #1	bra	@3@2	cmp #$100	blt	@3	lda #$FF@3	IF		((&bytenow AND %0000000000000001)=0) THEN			sta	TempValue	ELSEIF ((&bytenow AND %0000000000000001)=1) THEN			xba			ora	TempValue			sta	[DestPtr],y			iny			iny	ENDIF	lda &IDeltX,x	clc	adc	ExpMAEDA	sta ExpMAEDA	;	Now, bump SrcPtr if necessary	IF		(&samplewidth=3) THEN		IF (&phase=15) THEN; we're in 3-bit expansion, phase 15			clc			lda #6			adc	SrcPtr			sta	SrcPtr			bcc	@5			inc	SrcPtr+2@5		ENDIF	ELSEIF	(&samplewidth=4) THEN		IF	(&phase=15) THEN; we're in 4-bit expansion, phase 15			clc			lda #8			adc	SrcPtr			sta	SrcPtr			bcc	@6			inc	SrcPtr+2@6		ENDIF	ENDIF		MEND	MACRO&lab	DoItToIt3B		LCLA	&bytenumber&bytenumber	SETA	0&lab		WHILE &bytenumber<=15 DO		ExpandingMan	3,&bytenumber&bytenumber	SETA &bytenumber+1		ENDW	MEND	MACRO&lab	DoItToIt4B		LCLA	&bytenumber&bytenumber	SETA	0&lab		WHILE &bytenumber<=15 DO		ExpandingMan	4,&bytenumber&bytenumber	SETA &bytenumber+1		ENDW	MEND	MACRO&lab	IDelt3BTable		LCLA	&IPt		LCLA	&bb		LCLA	&cc		LCLA	&dd&lab&IPt	SETA	0		WHILE &IPt<=42 DO		IF		(&IPt=0) THEN&cc		SETA	0		ELSEIF	(&IPt=1) THEN&cc		SETA	3		ELSEIF	(&IPt=2) THEN&cc		SETA	4		ELSEIF	(&IPt=3) THEN&cc		SETA	5		ELSEIF	(&IPt=4) THEN&cc		SETA	6		ELSEIF	(&IPt=5) THEN&cc		SETA	7		ELSEIF	(&IPt=6) THEN&cc		SETA	8		ELSEIF	(&IPt=7) THEN&cc		SETA	9		ELSEIF	(&IPt=8) THEN&cc		SETA	10		ELSEIF	(&IPt=9) THEN&cc		SETA	11		ELSEIF	(&IPt=10) THEN&cc		SETA	12		ELSEIF	(&IPt=11) THEN&cc		SETA	13		ELSEIF	(&IPt=12) THEN&cc		SETA	15		ELSEIF	(&IPt=13) THEN&cc		SETA	16		ELSEIF	(&IPt=14) THEN&cc		SETA	18		ELSEIF	(&IPt=15) THEN&cc		SETA	20		ELSEIF	(&IPt=16) THEN&cc		SETA	22		ELSEIF	(&IPt=17) THEN&cc		SETA	24		ELSEIF	(&IPt=18) THEN&cc		SETA	26		ELSEIF	(&IPt=19) THEN&cc		SETA	29		ELSEIF	(&IPt=20) THEN&cc		SETA	32		ELSEIF	(&IPt=21) THEN&cc		SETA	35		ELSEIF	(&IPt=22) THEN&cc		SETA	39		ELSEIF	(&IPt=23) THEN&cc		SETA	43		ELSEIF	(&IPt=24) THEN&cc		SETA	47		ELSEIF	(&IPt=25) THEN&cc		SETA	52		ELSEIF	(&IPt=26) THEN&cc		SETA	57		ELSEIF	(&IPt=27) THEN&cc		SETA	63		ELSEIF	(&IPt=28) THEN&cc		SETA	69		ELSEIF	(&IPt=29) THEN&cc		SETA	76		ELSEIF	(&IPt=30) THEN&cc		SETA	84		ELSEIF	(&IPt=31) THEN&cc		SETA	92		ELSEIF	(&IPt=32) THEN&cc		SETA	102		ELSEIF	(&IPt=33) THEN&cc		SETA	112		ELSEIF	(&IPt=34) THEN&cc		SETA	123		ELSEIF	(&IPt=35) THEN&cc		SETA	135		ELSEIF	(&IPt=36) THEN&cc		SETA	149		ELSEIF	(&IPt=37) THEN&cc		SETA	164		ELSEIF	(&IPt=38) THEN&cc		SETA	180		ELSEIF	(&IPt=39) THEN&cc		SETA	198		ELSEIF	(&IPt=40) THEN&cc		SETA	218		ELSEIF	(&IPt=41) THEN&cc		SETA	240		ELSEIF	(&IPt=42) THEN&cc		SETA	264		ENDIF&bb		SETA	&cc>>1&dd		SETA	&cc+&bb		DC.W	0, &bb, &cc, &dd, 0, -&bb, -&cc, -&dd&IPt	SETA &IPt+1		ENDW	MEND	MACRO&lab	IDeltX3BTable		LCLA	&IPt		LCLA	&cc		LCLA	&ee&lab&IPt	SETA	0		WHILE &IPt<=42 DO		IF		(&IPt=0) THEN&cc		SETA	0		ELSEIF	(&IPt=1) THEN&cc		SETA	3		ELSEIF	(&IPt=2) THEN&cc		SETA	4		ELSEIF	(&IPt=3) THEN&cc		SETA	5		ELSEIF	(&IPt=4) THEN&cc		SETA	6		ELSEIF	(&IPt=5) THEN&cc		SETA	7		ELSEIF	(&IPt=6) THEN&cc		SETA	8		ELSEIF	(&IPt=7) THEN&cc		SETA	9		ELSEIF	(&IPt=8) THEN&cc		SETA	10		ELSEIF	(&IPt=9) THEN&cc		SETA	11		ELSEIF	(&IPt=10) THEN&cc		SETA	12		ELSEIF	(&IPt=11) THEN&cc		SETA	13		ELSEIF	(&IPt=12) THEN&cc		SETA	15		ELSEIF	(&IPt=13) THEN&cc		SETA	16		ELSEIF	(&IPt=14) THEN&cc		SETA	18		ELSEIF	(&IPt=15) THEN&cc		SETA	20		ELSEIF	(&IPt=16) THEN&cc		SETA	22		ELSEIF	(&IPt=17) THEN&cc		SETA	24		ELSEIF	(&IPt=18) THEN&cc		SETA	26		ELSEIF	(&IPt=19) THEN&cc		SETA	29		ELSEIF	(&IPt=20) THEN&cc		SETA	32		ELSEIF	(&IPt=21) THEN&cc		SETA	35		ELSEIF	(&IPt=22) THEN&cc		SETA	39		ELSEIF	(&IPt=23) THEN&cc		SETA	43		ELSEIF	(&IPt=24) THEN&cc		SETA	47		ELSEIF	(&IPt=25) THEN&cc		SETA	52		ELSEIF	(&IPt=26) THEN&cc		SETA	57		ELSEIF	(&IPt=27) THEN&cc		SETA	63		ELSEIF	(&IPt=28) THEN&cc		SETA	69		ELSEIF	(&IPt=29) THEN&cc		SETA	76		ELSEIF	(&IPt=30) THEN&cc		SETA	84		ELSEIF	(&IPt=31) THEN&cc		SETA	92		ELSEIF	(&IPt=32) THEN&cc		SETA	102		ELSEIF	(&IPt=33) THEN&cc		SETA	112		ELSEIF	(&IPt=34) THEN&cc		SETA	123		ELSEIF	(&IPt=35) THEN&cc		SETA	135		ELSEIF	(&IPt=36) THEN&cc		SETA	149		ELSEIF	(&IPt=37) THEN&cc		SETA	164		ELSEIF	(&IPt=38) THEN&cc		SETA	180		ELSEIF	(&IPt=39) THEN&cc		SETA	198		ELSEIF	(&IPt=40) THEN&cc		SETA	218		ELSEIF	(&IPt=41) THEN&cc		SETA	240		ELSEIF	(&IPt=42) THEN&cc		SETA	264		ENDIF&ee		SETA	&cc>>2		DC.W	&ee, &ee, &ee, &ee, -&ee, -&ee, -&ee, -&ee&IPt	SETA &IPt+1		ENDW	MEND		MACRO&lab	NewIPoint3BTable		LCLA	&IPt		LCLA	&bb		LCLA	&cc		LCLA	&dd&lab&IPt	SETA	0		WHILE &IPt<=42 DO&bb		SETA	(&max(&IPt-1,1))<<4&cc		SETA	(&min(&IPt+2,42))<<4&dd		SETA	(&min(&IPt+5,42))<<4		DC.W	&bb, &bb, &cc, &dd, &bb, &bb, &cc, &dd&IPt	SETA &IPt+1		ENDW	MEND	MACRO&lab	IDelt4BTable		LCLA	&IPt		LCLA	&bb		LCLA	&cc		LCLA	&dd&lab&IPt	SETA	0		WHILE &IPt<=42 DO		IF		(&IPt=0) THEN&cc		SETA	0		ELSEIF	(&IPt=1) THEN&cc		SETA	3		ELSEIF	(&IPt=2) THEN&cc		SETA	4		ELSEIF	(&IPt=3) THEN&cc		SETA	5		ELSEIF	(&IPt=4) THEN&cc		SETA	6		ELSEIF	(&IPt=5) THEN&cc		SETA	7		ELSEIF	(&IPt=6) THEN&cc		SETA	8		ELSEIF	(&IPt=7) THEN&cc		SETA	9		ELSEIF	(&IPt=8) THEN&cc		SETA	10		ELSEIF	(&IPt=9) THEN&cc		SETA	11		ELSEIF	(&IPt=10) THEN&cc		SETA	12		ELSEIF	(&IPt=11) THEN&cc		SETA	13		ELSEIF	(&IPt=12) THEN&cc		SETA	15		ELSEIF	(&IPt=13) THEN&cc		SETA	16		ELSEIF	(&IPt=14) THEN&cc		SETA	18		ELSEIF	(&IPt=15) THEN&cc		SETA	20		ELSEIF	(&IPt=16) THEN&cc		SETA	22		ELSEIF	(&IPt=17) THEN&cc		SETA	24		ELSEIF	(&IPt=18) THEN&cc		SETA	26		ELSEIF	(&IPt=19) THEN&cc		SETA	29		ELSEIF	(&IPt=20) THEN&cc		SETA	32		ELSEIF	(&IPt=21) THEN&cc		SETA	35		ELSEIF	(&IPt=22) THEN&cc		SETA	39		ELSEIF	(&IPt=23) THEN&cc		SETA	43		ELSEIF	(&IPt=24) THEN&cc		SETA	47		ELSEIF	(&IPt=25) THEN&cc		SETA	52		ELSEIF	(&IPt=26) THEN&cc		SETA	57		ELSEIF	(&IPt=27) THEN&cc		SETA	63		ELSEIF	(&IPt=28) THEN&cc		SETA	69		ELSEIF	(&IPt=29) THEN&cc		SETA	76		ELSEIF	(&IPt=30) THEN&cc		SETA	84		ELSEIF	(&IPt=31) THEN&cc		SETA	92		ELSEIF	(&IPt=32) THEN&cc		SETA	102		ELSEIF	(&IPt=33) THEN&cc		SETA	112		ELSEIF	(&IPt=34) THEN&cc		SETA	123		ELSEIF	(&IPt=35) THEN&cc		SETA	135		ELSEIF	(&IPt=36) THEN&cc		SETA	149		ELSEIF	(&IPt=37) THEN&cc		SETA	164		ELSEIF	(&IPt=38) THEN&cc		SETA	180		ELSEIF	(&IPt=39) THEN&cc		SETA	198		ELSEIF	(&IPt=40) THEN&cc		SETA	218		ELSEIF	(&IPt=41) THEN&cc		SETA	240		ELSEIF	(&IPt=42) THEN&cc		SETA	264		ENDIF&dd		SETA	&cc>>2&bb		SETA	&cc>>1		DC.W	0, &dd, &bb, (&bb+&dd), &cc, (&cc+&dd), (&cc+&bb), (&cc+&bb+&dd)		DC.W	0, -&dd, -&bb, -(&bb+&dd), -&cc, -(&cc+&dd), -(&cc+&bb), -(&cc+&bb+&dd)&IPt	SETA &IPt+1		ENDW	MEND	MACRO&lab	IDeltX4BTable		LCLA	&IPt		LCLA	&cc		LCLA	&ee&lab&IPt	SETA	0		WHILE &IPt<=42 DO		IF		(&IPt=0) THEN&cc		SETA	0		ELSEIF	(&IPt=1) THEN&cc		SETA	3		ELSEIF	(&IPt=2) THEN&cc		SETA	4		ELSEIF	(&IPt=3) THEN&cc		SETA	5		ELSEIF	(&IPt=4) THEN&cc		SETA	6		ELSEIF	(&IPt=5) THEN&cc		SETA	7		ELSEIF	(&IPt=6) THEN&cc		SETA	8		ELSEIF	(&IPt=7) THEN&cc		SETA	9		ELSEIF	(&IPt=8) THEN&cc		SETA	10		ELSEIF	(&IPt=9) THEN&cc		SETA	11		ELSEIF	(&IPt=10) THEN&cc		SETA	12		ELSEIF	(&IPt=11) THEN&cc		SETA	13		ELSEIF	(&IPt=12) THEN&cc		SETA	15		ELSEIF	(&IPt=13) THEN&cc		SETA	16		ELSEIF	(&IPt=14) THEN&cc		SETA	18		ELSEIF	(&IPt=15) THEN&cc		SETA	20		ELSEIF	(&IPt=16) THEN&cc		SETA	22		ELSEIF	(&IPt=17) THEN&cc		SETA	24		ELSEIF	(&IPt=18) THEN&cc		SETA	26		ELSEIF	(&IPt=19) THEN&cc		SETA	29		ELSEIF	(&IPt=20) THEN&cc		SETA	32		ELSEIF	(&IPt=21) THEN&cc		SETA	35		ELSEIF	(&IPt=22) THEN&cc		SETA	39		ELSEIF	(&IPt=23) THEN&cc		SETA	43		ELSEIF	(&IPt=24) THEN&cc		SETA	47		ELSEIF	(&IPt=25) THEN&cc		SETA	52		ELSEIF	(&IPt=26) THEN&cc		SETA	57		ELSEIF	(&IPt=27) THEN&cc		SETA	63		ELSEIF	(&IPt=28) THEN&cc		SETA	69		ELSEIF	(&IPt=29) THEN&cc		SETA	76		ELSEIF	(&IPt=30) THEN&cc		SETA	84		ELSEIF	(&IPt=31) THEN&cc		SETA	92		ELSEIF	(&IPt=32) THEN&cc		SETA	102		ELSEIF	(&IPt=33) THEN&cc		SETA	112		ELSEIF	(&IPt=34) THEN&cc		SETA	123		ELSEIF	(&IPt=35) THEN&cc		SETA	135		ELSEIF	(&IPt=36) THEN&cc		SETA	149		ELSEIF	(&IPt=37) THEN&cc		SETA	164		ELSEIF	(&IPt=38) THEN&cc		SETA	180		ELSEIF	(&IPt=39) THEN&cc		SETA	198		ELSEIF	(&IPt=40) THEN&cc		SETA	218		ELSEIF	(&IPt=41) THEN&cc		SETA	240		ELSEIF	(&IPt=42) THEN&cc		SETA	264		ENDIF&ee		SETA	&cc>>3		DC.W	&ee, &ee, &ee, &ee, &ee, &ee, &ee, &ee		DC.W	-&ee, -&ee, -&ee, -&ee, -&ee, -&ee, -&ee, -&ee&IPt	SETA &IPt+1		ENDW	MEND		MACRO&lab	NewIPoint4BTable		LCLA	&IPt		LCLA	&aa		LCLA	&bb		LCLA	&cc		LCLA	&dd		LCLA	&ee&lab&IPt	SETA	0; -1 -1 -1 -1 2 4 6 8		WHILE &IPt<=42 DO&aa		SETA	(&max(&IPt-1,1))<<5&bb		SETA	(&min(&IPt+2,42))<<5&cc		SETA	(&min(&IPt+4,42))<<5&dd		SETA	(&min(&IPt+6,42))<<5&ee		SETA	(&min(&IPt+8,42))<<5		DC.W	&aa, &aa, &aa, &aa, &bb, &cc, &dd, &ee		DC.W	&aa, &aa, &aa, &aa, &bb, &cc, &dd, &ee&IPt	SETA &IPt+1		ENDW	MEND;------------------------------------------;; Equates from procedure ACEDataSeg;;------------------------------------------SystemCall	equ $0000UserCall	equ $8000HighByte	equ $FF00LowByte		equ $00FFAllBits		equ %1111111111111111Bit0		equ %0000000000000001Bit1		equ %0000000000000010Bit2		equ %0000000000000100Bit3		equ %0000000000001000Bit4		equ %0000000000010000ZeroCrossing equ $80CompCallNum	equ $9; To be compatible with Apple standards, FALSE must be zero,;   TRUE must be non-zero.  To be compatible with Pascal & Modula-2,;   TRUE must be specifically 1.TRUE	equ $1FALSE	equ $0; ACE Condition Codes (codes at or above ErrorCondition imply carry set...;   codes below ErrorCondition imply carry clear on function return).ErrorCondition	equ $0001***********************************************************  ACE Audio Compression & Expansion Equates**  Copyright (C) 1988*  Apple Computer, Inc.*  All Rights Reserved**********************************************************ACENoError			equ $0000ACEIsActive			equ $1D01ACEBadDP			equ $1D02ACENotActive		equ $1D03ACENoSuchParam		equ $1D04ACEBadMethod		equ $1D05ACEBadSrc			equ $1D06ACEBadDest			equ $1D07ACEDataOverlap		equ $1D08ACENotImplemented	equ $1DFF; Miscellaneous constantsVersionNumber	equ $0103			;5-Feb-92 DALBlockSize		equ 512DPASize	equ 	256					; Size of DP area needed by ACE; Predefined locations in ACE Direct Page.; This layout defines fixed workspace for all calls.; Individual calls may use locations LocalArea..$FF for local workspace.; 90.05.23 JAM:  The direct-page locations from 00..saxelsize-1 are;	reserved for saxel information.  In version 1.2,;	only the first 4 bytes are actually used.;	Now, after every call to ACEExpand, the ACE state;	information to be inherited by the SUBSEQUENT call;	to ACEExpand is left in DP locations 00..saxelsize-1.;ExpIPoint	equ $00ExpMAEDA	equ $02** Since only the first four bytes are currently used, GetACEExpState will return** $00s for the last 12 bytes.  25-Sep-90 DALsaxelsize	equ $10	; JAM 90.05.23OldDP		equ 0+saxelsize		; Caller's DP saved in tool DP 0..1.DPToolNum	equ 2+saxelsize		; Tool number saved	in tool DP 2..3.OldBank		equ $4+saxelsize	; DBR value on entry (8bits LSB=MSB)ErrSP		equ $6+saxelsize	; Cutback SP in case of error.ErrCode		equ $8+saxelsizeIQUNWPtr	equ $A+saxelsize	; Cur. IQUNW ptr in	tool DP $A..D.IPShiftPtr	equ $E+saxelsize	; Cur. IPShift Ptr in tool DP $E..11.SrcPtr		equ $12+saxelsizeDestPtr		equ $16+saxelsizeNumBits		equ $1A+saxelsizeNumBlks		equ $1C+saxelsizeCompIPoint	equ $1E+saxelsizeCompMAEDA	equ $20+saxelsizeLocalArea	equ $80				; Start of call-local workspace in DP.	INCLUDE 'm16.util2'	INCLUDE 'm16.memory'	INCLUDE 'm16.locator';-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY ACEStatus	ENTRY ACEBootInit	ENTRY ACECompBegin	ENTRY ACECompress	ENTRY ACEExpBegin	ENTRY ACEExpand	ENTRY ACEInfo	ENTRY ACEReset	ENTRY ACEShutDown	ENTRY ACEStartUp	ENTRY ACEVersion	ENTRY DeRefHandle	ENTRY EndDefIQU	ENTRY NotImp	Entry GetACEExpState		;added 25-Sep-90 DAL	Entry SetACEExpState		;added 25-Sep-90 DAL*         absaddr on*         instime on	PRINT GEN, NOMDIR, SYM, DATA*         KEEP td	MACHINE M65816	longa on	longi on		ACTR	16384	EXPORT CallTableCallTable	PROC	DC.L (TheEnd-CallTable)/4	DC.L ACEBootInit-1	DC.L ACEStartUp-1	DC.L ACEShutDown-1	DC.L ACEVersion-1	DC.L ACEReset-1	DC.L ACEStatus-1	DC.L ACEInfo-1	DC.L NotImp-1	DC.L ACECompress-1	DC.L ACEExpand-1	DC.L ACECompBegin-1	DC.L ACEExpBegin-1	DC.L GetACEExpState-1		;added 25-Sep-90 DAL	DC.L SetACEExpState-1		;added 25-Sep-90 DALTheEnd		ENDP	EXPORT ACEDataSegACEDataSeg	PROC; DEFAULT WAVEMODELS	EXPORT DefWMAreaDefWMArea	EXPORT DefIQUNWDefIQUNW	DC.W (EndDefIQU-StDefIQU)/2	EXPORT StDefIQUStDefIQU	DC.W	3,		4,		5,		6,		7,		8,		9	DC.W	10,		11,		12,		13,		15,		16,		18	DC.W	20,		22,		24,		26,		29,		32,		35	DC.W	39,		43,		47,		52,		57,		63,		69	DC.W	76,		84,		92,		102,	112,	123,	135	DC.W	149,	164,	180,	198,	218,	240,	264	EXPORT EndDefIQUEndDefIQU	EXPORT DefIPShiftDefIPShift	DC.W 4										; packing is to 3..4 bits	DC.W 5										; starting item: 3-bit shifts	DC.W 4										; number of 3-bit shifts	DC.W 9										; starting item: 4-bit shifts	DC.W 8										; number of 4-bit shifts	DC.W -1,-1,2,5								; 3-bit shift values	DC.W -1,-1,-1,-1,2,4,6,8 					; 4-bit shift values	EXPORT DefWMEndDefWMEnd	ENDP	EXPORT ACEBootInitACEBootInit	PROC	lda #ACENoError	clc	rtl	ENDP	EXPORT ACEStartUpACEStartUp	PROCRTL1	equ 1RTL2	equ RTL1+3DPToUse	equ RTL2+3ToolNum	equ 5TempTN	equ 1; If non-zero acc on entry, we have direct page, so this call is redundant.	ldy #ACENoError								; Y is working cond. code (init = 0)	cmp #0										; Acc should have low word of WAP.	beq DoTheJob								; If zero, no DP installed.	ldy #ACEIsActive							; Condition code must be in y	brl DPUnchanged; Here, we know that we have a zero acc, so we are really starting upDoTheJob	lda DPToUse,s	bne GetGoing	ldy #ACEBadDP								; If param is zero,	it's NO GOOD!	brl DPUnchangedGetGoing	pha											; temp storage for DP	phx											; temporary storage	for tool/fn number	phy											;   and current error code	pushword #SystemCall	phx											; still contains this tool/fn number	pushword #0	pha	lda ToolNum,s	and #LowByte	sta ToolNum,s	_SetWAP	ply											; get back the error code in y	plx											;   and the tool/fn	number.	pla											; got the DP back, too	phd											; temp store current DP	tcd	lda #1	sta CompIPoint								; CompIPoint initially 1	stz ExpIPoint								;  ExpIPoint initially 0	lda #ZeroCrossing	sta CompMAEDA	sta ExpMAEDA	pld											; restore direct page of entryDPUnchanged	lda RTL2+1,s	sta DPToUse,s	lda RTL2-1,s	sta DPToUse-2,s	lda RTL1,s	sta DPToUse-4,s	pla;  here, we expect byte-size condition code in y and tool, fn number in x	cpy #ErrorCondition	bcc Penultimate	txa	xba	and #HighByte	pha	tya	ora TempTN,s	ply	bra FinalOutPenultimate	tyaFinalOut	rtl	ENDP	EXPORT ACEShutDownACEShutDown	PROC***	cmp #0					; WAP in acc, zero if ACE inactive	tay						;25-Sep-90 DAL	beq NotActive			; should be ACENotActive Error	pushword #SystemCall 	; system tool call; tool number in X(LSB)...call number in X(MSB)	txa						; put it where we can mess with it	and #LowByte			; strip off call number; reset WAP to zero	pha						; Tool # whose WAP we want to change	pushword #0				; Put a long-	pushword #0				;   word zero into that baby!	_SetWAP					; And do the job!	lda #ACENoError			; The condition code.	bra GoHomeNotActive**	txa						; call number/tool number now in acc**	and #LowByte			; save tool number only**	xba						; put it in msb**	ora #ACENotActive		; condition code in	lsb	lda #ACENotActive		;25-Sep-90 DALGoHome	cmp #ErrorCondition		; Sets carry if error.	rtl	ENDP	EXPORT ACEVersionACEVersion	PROCRTL1	equ 1RTL2	equ RTL1+3VerNum	equ RTL2+3	lda #VersionNumber	sta VerNum,s	lda #ACENoError	clc						;25-Sep-90 DAL (was cmp #ErrorCondition)	rtl	ENDP	EXPORT ACEResetACEReset	PROC	lda #ACENoError	clc						;25-Sep-90 DAL (was cmp #ErrorCondition)	rtl	ENDP	EXPORT ACEStatusACEStatus	PROCRTL1	equ 1RTL2	equ RTL1+3RetnVal	equ RTL2+3	cmp #FALSE				; acc = WAP(lsb) = zero if ACE inactive	beq GoHomeImActive	lda #TRUEGoHome	sta RetnVal,s	lda #ACENoError	clc						;25-Sep-90 DAL	rtl	ENDP	EXPORT ACEInfoACEInfo	PROCTempTN	equ 1RTL1	equ 1RTL2	equ RTL1+3InfoNum	equ RTL2+3RetnVal	equ InfoNum+2	ldy #ACENoError	; init. value for condition code	lda InfoNum,s	beq DoTheJob	; actually, should be bad param error	ldy #ACENoSuchParam	bra GoHomeDoTheJob		; 	lda #DPASize	; size of required DP area in bytes	sta RetnVal,s	lda #0	; high word is always zero	sta RetnVal+2,s; Now ...GoHome		; 	lda RTL2+1,s	sta InfoNum,s	lda RTL2-1,s	sta InfoNum-2,s	lda RTL1,s	sta InfoNum-4,s	pla	; get rid of wordsize garbage on stack;  here, we expect byte-size condition code in y and tool, fn number in x	cpy #ErrorCondition	bcc Penultimate	txa	xba	and #HighByte	pha	tya	ora TempTN,s	ply	bra FinalOutPenultimate		; 	tyaFinalOut	rtl	ENDP	EXPORT NotImpNotImp	PROC**	txa**	xba**	ora #ACENotImplemented**	cmp #ErrorCondition	lda #ACENotImplemented	sec	rtl	ENDP	EXPORT ACECompressACECompress	PROC	EXPORT ACEExpandACEExpandTempTN		EQU 1RTL1		EQU 1RTL2		EQU RTL1+3Method		EQU RTL2+3NBlks		EQU Method+2DestOffset	EQU NBlks+2Dest		EQU DestOffset+4SrcOffset	EQU Dest+4Src			EQU SrcOffset+4ISABUN		EQU LocalAreaIDelt		EQU ISABUN+2IDeltH		EQU IDelt+2IDeltQ		EQU IDeltH+2IDeltX		EQU IDeltQ+2IDecM		EQU IDeltX+2IBit0		EQU IDecM+2IBit1		EQU IBit0+2IBit2		EQU IBit1+2IBit3		EQU IBit2+2BitNow		EQU IBit3+2ByteNow		EQU BitNow+2TempValue	EQU ByteNow+2SrcSize		EQU TempValue+4SrcEND		EQU SrcSize+4DestSize	EQU SrcEND+4DestEND		EQU DestSize+4ExpMask		EQU DestEND+4Negative	EQU ExpMask+2buff		EQU	Negative+2		; this is a four-word (8 byte) buffer	ldy #0	; I HOPE zeroing y is overkill!; If zero acc on entry, we have no direct page, so this call cannot work.	cmp #0	bne DoTheJob	ldy #ACENotActive			; Condition code must be in y	brl DPUnchangedDoTheJob	pha							; Save tool's DP space pointer for now	tdc							; Get ready to save	caller's DP ptr	pld							; Tool's DP space is active	sta OldDP					; Caller's DP Pointer is safe & snug	stx DPToolNum				; In case of error ... tool number here	sty ErrCode					; In case of error ... error code here	tsc							; In case of error ...	sta ErrSP					;    ... cutback stack pointer here	phb							; In case tool changes	phb							;    it, put caller's	pla							;    data bank register	sta OldBank					;    away for safekeeping.	lda #4	sta NumBits	lda Method,s	cmp #1	beq K