nd	status are preserved.  Direct page not used.; Handle is LOCKED upon exit.	php	phx	pha	lda 9,S	tax									; x has address of handle	lda 11,S							; a has bank of handle	phb	xba	pha	xba	phx	pha	phx	_HLock	plx	plb	plb									; now in the right bank	lda |0,x	sta 10,s							; lsw of pointer	lda |2,x	sta 12,S							; msw of pointer	plb									; back in the old bank	pla									; restore the world	plx									; aren't we nice??!!??	plp	rtl									; gehen wir nach hause...	ENDP	EXPORT ACECompBeginACECompBegin	PROC	cmp #0								; WAP in acc, zero if ACE inactive	beq NotActive						; should be ACENotActive Error	phd	tcd	lda #1	sta CompIPoint	lda #ZeroCrossing	sta CompMAEDA	pld	lda #ACENoError						; JAM 14-Apr-88	bra GoHomeNotActive**	txa									; call number/tool number now in acc**	and #LowByte						; save tool number only**	xba									; put it in msb**	ora #ACENotActive					; condition code in	lsb	lda #ACENotActive					; 25-Sep-90 DALGoHome	cmp #ErrorCondition					; Sets carry if error.	rtl	ENDP	EXPORT ACEExpBeginACEExpBegin	PROC	cmp #0								; WAP in acc, zero if ACE inactive	beq NotActive						; should be ACENotActive Error	phd	tcd	stz ExpIPoint	lda #ZeroCrossing	sta ExpMAEDA	pld	lda #ACENoError						; JAM 14-Apr-88	bra GoHomeNotActive**	txa									; call number/tool number now in acc**	and #LowByte						; save tool number only**	xba									; put it in msb**	ora #ACENotActive					; condition code in	lsb	lda #ACENotActive					; 25-Sep-90 DALGoHome	cmp #ErrorCondition					; Sets carry if error.	rtl	ENDP**************************************************************** $0D1D GetACEExpState(BufferPointer)** New call 25-Sep-90 DAL** All we have to do in this call is copy 16 bytes from the* beginning of our direct page into the buffer.** Actually, only the first 4 bytes are used, so we copy those* and then fill the rest of the buffer with $0000.***************************************************************GetACEExpState	proc export	tax	beq NotActive	phd	tsc	tcd	ldy #0@copy	lda >0,x	sta [9],y	inx	inx	iny	iny	cpy #4			; currently only the first 4 saxel	bcc @copy		;	bytes are "live"	lda #0@zero	sta [9],y	iny	iny	cpy #SaxelSize	; JAM 91.07.21 - Use named equates, Dave!  :-)	bcc @zero		; JAM 91.07.21 - This fixes BRC #1008113		pld	entry NoError4NoError4	ldx #0	bra Strip4	entry NotActiveNotActive	ldx #ACENotActiveStrip4	ldy #4	jml $e10184		;ToStrip	EndP	**************************************************************** $0E1D SetACEExpState(BufferPointer)** New call 25-Sep-90 DAL** The buffer pointer is 16 bytes.  All we have to do in this* call is copy those bytes onto our direct page.***************************************************************SetACEExpState	proc export	import NotActive	import NoError4	tax	beq NotActive	phd	tsc	tcd	ldy #0@copy	lda [9],y	sta >0,x	inx	inx	iny	iny	cpy #SaxelSize	bcc @copy	pld	bra NoError4	EndP		END